# ------------------------------------------------------------------ permutation R_k
def permuted_rss_block(y, pan, tag, n_perm, rng, cache={}):
    """R_k with permutation null: shuffle the class-k covariate at RUN level within
    season, rebuild that block's columns (splines rebuilt for age/week), recompute
    R_k = 1 - RSS(full-with-permuted-k)/RSS(working model w/o k)."""
    X, names, blocks = build_blocks(pan)
    cols = np.array(block_cols(names, tag), int)
    run_ids = pan["run_id"].to_numpy(int)
    season_of_run = pd.Series(pan["season"].to_numpy(int)).groupby(run_ids).first()
    positions = pd.Series(np.arange(len(pan))).groupby(run_ids).first()
    first_idx = positions.to_numpy()
    run_of_first = run_ids[first_idx]
    sea_of_first = season_of_run.to_numpy()[first_idx]

    r_full = rss_of(y, X)
    keep = np.setdiff1d(np.arange(X.shape[1]), cols)
    r_red = rss_of(y, X[:, keep])
    r_obs = 1.0 - r_full / r_red

    nulls = np.empty(n_perm)
    for i in range(n_perm):
        new_labels = _shuffle_labels(pan, tag, first_idx, run_of_first, sea_of_first,
                                     rng)
        Xp = X.copy()
        Xp[:, cols] = _rebuild_block(pan, tag, new_labels, first_idx, run_ids)
        nulls[i] = 1.0 - rss_of(y, Xp) / r_red
    mu, sd = float(nulls.mean()), float(nulls.std(ddof=1))
    q95 = float(np.quantile(nulls, 0.95))
    pval = float((np.sum(nulls >= r_obs) + 1.0) / (n_perm + 1.0))
    z = (r_obs - mu) / sd if sd > 0 else np.nan
    return dict(R=r_obs, p_perm=pval, null_q95=q95, z_perm=z, null_mean=mu)


def _shuffle_labels(pan, tag, first_idx, run_of_first, sea_of_first, rng):
    """Label vector at run level, shuffled within season; expanded to rows."""
    if tag in ("pro", "industry", "multi"):
        base = pan.iloc[first_idx]
        if tag == "pro":
            v = base["pro"].to_numpy()
        elif tag == "industry":
            v = base["celebrity_industry"].to_numpy()
        else:
            v = base["multi_dance_week"].to_numpy()
    else:
        base = pan.iloc[first_idx]
        v = (base["celebrity_age_during_season"].to_numpy(float) if tag == "age"
             else base["week"].to_numpy(float))
    pv = v.copy()
    for s in np.unique(sea_of_first):
        m = sea_of_first == s
        pv[m] = rng.permutation(v[m])
    expand = pd.Series(pv, index=run_of_first).reindex(pan["run_id"].to_numpy(int))
    return expand.to_numpy()


def _rebuild_block(pan, tag, labels, first_idx, run_ids):
    """Rebuild the class-k design columns from (possibly permuted) labels."""
    if tag in ("pro", "industry"):
        s = pd.Series(labels).astype("category")
        d = pd.get_dummies(s, drop_first=False)
        return d.to_numpy(float)[:, 1:]          # drop first level (ref cell)
    if tag == "age":
        return rcs_design(labels.astype(float), RCS_KNOTS_AGE)
    if tag == "week":
        return rcs_design(labels.astype(float), RCS_KNOTS_WEEK)
    if tag == "multi":
        return labels.astype(float)[:, None]
    raise ValueError(tag)
