def permutation_decomp(pan, yJ, yF, X, names, n_perm=N_PERM, seed=SEED):
    """Partial R^2 of each block with within-season run-level label permutations."""
    results = []
    run_ids = pan["run_id"].to_numpy(int)
    first_idx = pd.Series(np.arange(len(pan))).groupby(run_ids).first().to_numpy()
    sea = pan["season"].to_numpy(int)

    def labels_of(tag):
        if tag == "pro":
            return pan["pro"].to_numpy()
        if tag == "industry":
            return pan["celebrity_industry"].to_numpy()
        if tag == "age":
            return pan["celebrity_age_during_season"].to_numpy(float)
        if tag == "week":
            return pan["week"].to_numpy(float)
        if tag == "multi":
            return pan["multi_dance_week"].to_numpy(float)
        raise ValueError(tag)

    for tag in ("pro", "industry", "age", "week", "multi"):
        cols = np.array(block_cols(names, tag), int)
        # observed partial R2
        keep = np.setdiff1d(np.arange(X.shape[1]), cols)
        r_full_J = rss_of(yJ, X)
        r_full_F = rss_of(yF, X)
        r_red_J = rss_of(yJ, X[:, keep])
        r_red_F = rss_of(yF, X[:, keep])
        R_J = 1.0 - r_full_J / r_red_J
        R_F = 1.0 - r_full_F / r_red_F
        # permutation nulls (labels permuted at run level within season)
        lab0 = labels_of(tag)
        null_J, null_F = np.empty(n_perm), np.empty(n_perm)
        for i in range(n_perm):
            lab = lab0.copy()
            # shuffle within season
            for s in np.unique(sea):
                m = (pan["season"].to_numpy(int) == s)
                lab[m] = rng.permutation(lab0[m])
            # rebuild the permuted block using m2_data designs at row level
            if tag == "pro":
                Bp = rcs_design(np.ones(len(pan)), RCS_KNOTS_AGE)[:, :0]  # placeholder
                # categorical: rebuild via dummies from labels
                d = pd.get_dummies(lab.astype(str), drop_first=False)
                Bp = d.to_numpy(float)[:, 1:]
            elif tag == "industry":
                d = pd.get_dummies(lab.astype(str), drop_first=False)
                Bp = d.to_numpy(float)[:, 1:]
            elif tag == "age":
                Bp = rcs_design(lab.astype(float), RCS_KNOTS_AGE)
            elif tag == "week":
                Bp = rcs_design(lab.astype(float), RCS_KNOTS_WEEK)
            else:
                Bp = lab.astype(float)[:, None]
            XpJ = X.copy(); XpJ[:, cols] = Bp
            null_J[i] = 1.0 - rss_of(yJ, XpJ) / r_red_J
            null_F[i] = 1.0 - rss_of(yF, XpF := XpJ) / r_red_F
        results.append((tag, R_J, R_F, null_J, null_F))
    return results
