                                   if not nm.startswith(("pro_", "ind_", "age_"))]],
                            D_run, X[:, [i for i, nm in enumerate(names)
                                         if nm.startswith(("pro_", "ind_", "age_"))]])
    cols_pro = np.array(MA.block_cols(names, "pro"), int)
    # restricted model: y ~ season+week+multi + run dummies + pro
    keep = [i for i, nm in enumerate(names)
            if not nm.startswith("ind_")]           # industry absorbed by run FE
    Xr = X[:, keep]
    pro_cols_r = np.array([keep.index(i) for i in MA.block_cols(names, "pro")], int)
    for surf, y in (("judge", yJ), ("fan", yF)):
        r_full = MA.rss_of(y, Xr)
        r_red = MA.rss_of(y, np.delete(Xr, pro_cols_r, axis=1))
        out[f"R_pro_restricted_{surf}"] = round(1.0 - r_full / r_red, 4)
    return out


